package com.hireflow.api.application; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ApplicationRepository extends JpaRepository<JobApplication,Long>{List<JobApplication> findByCandidateEmailOrderByAppliedAtDesc(String email); long countByStatus(String status); Optional<JobApplication> findByJobIdAndCandidateEmail(Long jobId,String email);}